window.kbPageData["views/entry/k-a2f9bcd1d5de1658"] = {"key":"entry/k-a2f9bcd1d5de1658","state":{"route":"entry/k-a2f9bcd1d5de1658"},"node":{"id":"k-a2f9bcd1d5de1658","mode":"k","title":"“水稻+禾虫”生态种养","type":"原理与机制","domain":"经济","reading":"","intro":"","priority":100,"aliases":["稻田生态种养兼顾生态改善与经营增收"],"qs":["江苏 2024 C类 申论#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“水稻+禾虫”是在同一稻田种稻、养禾虫的绿色生态种养模式，通过禾虫的取食、钻洞等活动改善稻田生态，并通过销售稻米和禾虫获得收益。","review":{"definition":"“水稻+禾虫”是在同一稻田种稻、养禾虫的绿色生态种养模式，通过禾虫的取食、钻洞等活动改善稻田生态，并通过销售稻米和禾虫获得收益。","explanation":"材料1中，老王采用的模式停用除草剂、农药和化肥。禾虫取食腐烂的稻根和茎叶，有助于减少水稻病害，钻洞可松动土壤，排泄物可作有机肥。老王的稻米产量有所降低，但凭借优质优价，稻米这一项的收益仍不低于从前，出售禾虫又增加一项收入。归纳时应同时写出生态改善和种粮增收两方面成效。","references":[],"evidence":"禾虫会吃掉腐烂的稻根和茎叶、田里的浮游生物，减少水稻病害。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 申论#1":{"paper":"江苏 2024 C类 申论","n":1,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",1],"card":"34937ce9d0604e011b46a569","links":[{"id":"k-a2f9bcd1d5de1658","role":"直接考查","why":"禾虫取食腐烂稻根和茎叶、疏松土壤，优质稻米和禾虫销售共同支撑农户增收。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a2f9bcd1d5de1658":[["江苏 2024 C类 申论#1"]]}};
